export function createInMemoryReplayStore() {
    const store = new Map();
    function prune() {
        const now = Date.now();
        for (const [id, expiresAt] of store) {
            if (expiresAt > 0 && expiresAt <= now) {
                store.delete(id);
            }
        }
    }
    return {
        async add(id, expiresAt) {
            prune();
            store.set(id, expiresAt ?? 0);
        },
        async consume(id) {
            prune();
            if (!store.has(id))
                return false;
            store.delete(id);
            return true;
        },
    };
}
